    /**
     * Method to retrieve the Prediction via PredictionFetchOneSummary
     * @param 	summary PredictionFetchOneSummary 
     * @return 	PredictionFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Prediction getPrediction( PredictionFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "PredictionFetchOneSummary arg cannot be null" );
    	
    	Prediction entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Prediction
        	// --------------------------------------
        	CompletableFuture<Prediction> futureEntity = queryGateway.query(new FindPredictionQuery( new LoadPredictionFilter( summary.getPredictionId() ) ), ResponseTypes.instanceOf(Prediction.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Prediction with id " + summary.getPredictionId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


